)

var (
	threshold = flag.Int("t", 15, "minimum token sequence size as a clone")
	html      = flag.Bool("html", false, "output the results as HTML, including duplicate code fragments")
	plumbing  = flag.Bool("plumbing", false, "plumbing (easy-to-parse) output for consumption by scripts or tools")
	files     = flag.Bool("files", false, "read file names from stdin one at each line")
	vendor    = flag.Bool("vendor", false, "check files in vendor directory")
	verbose   = flag.Bool("v", false, "explain what is being done")
)

func init() {
	flag.IntVar(threshold, "threshold", 15, "minimum token sequence size as a clone")
	flag.BoolVar(verbose, "verbose", false, "explain what is being done")
}

func main() {
	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(), `Usage: dupl [flags] [paths]

Paths:
  If the given path is a file, dupl will use it regardless of
  the file extension. If it is a directory, it will recursively
  search for *.go files in that directory.

  If no path is given, dupl will recursively search for *.go
  files in the current directory.

Flags:
`)
		flag.PrintDefaults()
		fmt.Fprintf(flag.CommandLine.Output(), `
Examples:
  dupl -t 100
    	Search clones in the current directory of size at least
    	100 tokens.
  dupl $(find app/ -name '*_test.go')
    	Search for clones in tests in the app directory.
  find app/ -name '*_test.go' |dupl -files
    	The same as above.
`)
	}

	flag.Parse()

	if *html && *plumbing {
		log.Fatal("you can have either plumbing or HTML output")
	}

	var goFiles []string

	if *files {
		// Read file names from stdin
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			goFiles = append(goFiles, scanner.Text())
		}
		if err := scanner.Err(); err != nil {
			log.Fatal(err)
		}
	} else {
		paths := flag.Args()
		if len(paths) == 0 {
			paths = []string{"."}
		}
		for _, p := range paths {
			files, err := walkGo(p, *vendor)
			if err != nil {
				log.Fatal(err)
			}
			goFiles = append(goFiles, files...)
		}
	}

	if *verbose {
		log.Println("Building suffix tree")
	}

	// Build tokens from all files
	type FileTokens struct {
		path   string
		tokens []string
		lines  []int // line number for each token
	}

	var allFiles []FileTokens

	for _, f := range goFiles {
		tokens, lines, err := tokenizeFile(f)
		if err != nil {
			if *verbose {
				log.Printf("Error tokenizing %s: %v", f, err)
			}
			continue
		}
		if len(tokens) > 0 {
			allFiles = append(allFiles, FileTokens{
				path:   f,
				tokens: tokens,
				lines:  lines,
			})
		}
	}

	if *verbose {
		log.Println("Searching for clones")
	}

	// Find clones
	clones := findClones(allFiles, *threshold)

	// Output results
	if *html {
		outputHTML(clones, allFiles)
	} else if *plumbing {
		outputPlumbing(clones, allFiles)
	} else {
		outputNormal(clones, allFiles)
	}
}

func walkGo(root string, includeVendor bool) ([]string, error) {
	var result []string
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			if !includeVendor && info.Name() == "vendor" {
				return filepath.SkipDir
			}
			return nil
		}
		if strings.HasSuffix(path, ".go") {
			result = append(result, path)
		}
		return nil
	})
	return result, err
}

func tokenizeFile(filepath string) ([]string, []int, error) {
	source, err := ioutil.ReadFile(filepath)
	if err != nil {
		return nil, nil, err
	}

	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filepath, source, 0)
	if err != nil {
		return nil, nil, err
	}

	var tokens []string
	var lines []int

	// Walk through the AST and extract tokens
	v := &tokenVisitor{
		fset:   fset,
		tokens: &tokens,
		lines:  &lines,
	}
	v.visit(f)

	return tokens, lines, nil
}

type tokenVisitor struct {
	fset   *token.FileSet
	tokens *[]string
	lines  *[]int
}

func (v *tokenVisitor) visit(node interface{}) {
	if node == nil {
		return
	}

