	"os"
	"path/filepath"
	"sort"
	"strings"
)

var (
	flagThreshold = flag.Int("t", 15, "minimum token sequence size as a clone")
	flagHTML      = flag.Bool("html", false, "output the results as HTML, including duplicate code fragments")
	flagPlumbing  = flag.Bool("plumbing", false, "plumbing (easy-to-parse) output for consumption by scripts or tools")
	flagFiles     = flag.Bool("files", false, "read file names from stdin one at each line")
	flagVendor    = flag.Bool("vendor", false, "check files in vendor directory")
	flagVerbose   = flag.Bool("v", false, "explain what is being done")
)

func init() {
	flag.IntVar(flagThreshold, "threshold", 15, "minimum token sequence size as a clone")
	flag.BoolVar(flagVerbose, "verbose", false, "explain what is being done")
}

type TokenInfo struct {
	Type  token.Token
	Value string
	Line  int
	Col   int
	File  string
}

type CloneGroup struct {
	Signature  string
	Occurrences []CloneOccurrence
}

type CloneOccurrence struct {
	File      string
	StartLine int
	EndLine   int
	StartIdx  int
	EndIdx    int
}

func main() {
	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(), `Usage: dupl [flags] [paths]

Paths:
  If the given path is a file, dupl will use it regardless of
  the file extension. If it is a directory, it will recursively
  search for *.go files in that directory.

  If no path is given, dupl will recursively search for *.go
  files in the current directory.

Flags:
`)
		flag.PrintDefaults()
		fmt.Fprintf(flag.CommandLine.Output(), `
Examples:
  dupl -t 100
    	Search clones in the current directory of size at least
    	100 tokens.
  dupl $(find app/ -name '*_test.go')
    	Search for clones in tests in the app directory.
  find app/ -name '*_test.go' |dupl -files
    	The same as above.
`)
	}

	flag.Parse()

	if *flagHTML && *flagPlumbing {
		log.Fatal("you can have either plumbing or HTML output")
	}

	var goFiles []string

	if *flagFiles {
		// Read file names from stdin
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			goFiles = append(goFiles, scanner.Text())
		}
		if err := scanner.Err(); err != nil {
			log.Fatal(err)
		}
	} else {
		paths := flag.Args()
		if len(paths) == 0 {
			paths = []string{"."}
		}
		for _, p := range paths {
			files, err := walkGo(p, *flagVendor)
			if err != nil {
				log.Fatal(err)
			}
			goFiles = append(goFiles, files...)
		}
	}

	if *flagVerbose {
		log.Println("Building suffix tree")
	}

	// Parse tokens from all files
	var allTokens []TokenInfo
	fileMap := make(map[string][]TokenInfo)

	for _, f := range goFiles {
		tokens, err := tokenizeFile(f)
		if err != nil {
			if *flagVerbose {
				log.Printf("Error tokenizing %s: %v", f, err)
			}
			continue
		}
		if len(tokens) > 0 {
			fileMap[f] = tokens
			allTokens = append(allTokens, tokens...)
		}
	}

	if *flagVerbose {
		log.Println("Searching for clones")
	}

	// Find clones
	cloneGroups := findClones(fileMap, *flagThreshold)

	// Sort clones for consistent output
	sort.Slice(cloneGroups, func(i, j int) bool {
		if len(cloneGroups[i].Occurrences) != len(cloneGroups[j].Occurrences) {
			return len(cloneGroups[i].Occurrences) > len(cloneGroups[j].Occurrences)
		}
		if cloneGroups[i].Occurrences[0].File != cloneGroups[j].Occurrences[0].File {
			return cloneGroups[i].Occurrences[0].File < cloneGroups[j].Occurrences[0].File
		}
		return cloneGroups[i].Occurrences[0].StartLine < cloneGroups[j].Occurrences[0].StartLine
	})

	// Output results
	if *flagHTML {
		outputHTML(cloneGroups, fileMap)
	} else if *flagPlumbing {
		outputPlumbing(cloneGroups)
	} else {
		outputNormal(cloneGroups)
	}
}

func walkGo(root string, includeVendor bool) ([]string, error) {
	var result []string
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			if !includeVendor && info.Name() == "vendor" {
				return filepath.SkipDir
			}
			return nil
		}
		if strings.HasSuffix(path, ".go") {
			result = append(result, path)
		}
		return nil
	})
	return result, err
}

func tokenizeFile(filepath string) ([]TokenInfo, error) {
	source, err := ioutil.ReadFile(filepath)
	if err != nil {
		return nil, err
	}

	fset := token.NewFileSet()
	var s scanner.Scanner
	s.Init(fset.AddFile(filepath, fset.Base(), len(source)), source, nil, 0)

	var tokens []TokenInfo

	for {
		pos, tok, lit := s.Scan()
		if tok == token.EOF {
			break
		}
		p := fset.Position(pos)
		tokens = append(tokens, TokenInfo{
			Type:  tok,
			Value: lit,
			Line:  p.Line,
			Col:   p.Column,
			File:  filepath,
		})
	}

	return tokens, nil
}

func tokenToString(t TokenInfo) string {
	// For IDENT tokens, normalize them
	if t.Type == token.IDENT {
		return "IDENT"
	}
	// For other tokens, use type and value
	return fmt.Sprintf("%s:%s", t.Type.String(), t.Value)
}

func findClones(fileMap map[string][]TokenInfo, threshold int) []CloneGroup {
	// Build a map from signature to occurrences
	signatureMap := make(map[string][]CloneOccurrence)

	// For each file, find all token sequences >= threshold
	for filepath, tokens := range fileMap {
		// Find all maximal duplicate sequences for this file
		for i := 0; i < len(tokens); i++ {
			// Try sequences of increasing length starting at position i
			maxLen := 0
			var maxSig string

			for j := i + threshold; j <= len(tokens); j++ {
				sig := buildSignature(tokens[i:j])

				// Check if this signature appears elsewhere
				foundElsewhere := false
				for k := 0; k < len(tokens); k++ {
					if k == i {
						continue
					}
					if k+threshold <= len(tokens) && k+j-i <= len(tokens) {
						if buildSignature(tokens[k:k+j-i]) == sig {
							foundElsewhere = true
							break
						}
					}
				}

				if foundElsewhere {
					maxLen = j - i
					maxSig = sig
				} else {
					break
				}
			}

			if maxLen >= threshold {
				startLine := tokens[i].Line
				endLine := tokens[i+maxLen-1].Line

				signatureMap[maxSig] = append(signatureMap[maxSig], CloneOccurrence{
					File:      filepath,
					StartLine: startLine,
					EndLine:   endLine,
					StartIdx:  i,
					EndIdx:    i + maxLen - 1,
				})
			}
		}
	}

	// Actually this approach is still wrong. Let me think differently.
	// The real approach: find all signatures that appear multiple times in DIFFERENT files
	// OR multiple times in the SAME file

	signatureMap = make(map[string][]CloneOccurrence)

	// Build map of all contiguous sequences >= threshold
	for filepath, tokens := range fileMap {
		for i := 0; i <= len(tokens)-threshold; i++ {
			for j := i + threshold; j <= len(tokens); j++ {
				sig := buildSignature(tokens[i:j])
				startLine := tokens[i].Line
				endLine := tokens[j-1].Line

				signatureMap[sig] = append(signatureMap[sig], CloneOccurrence{
					File:      filepath,
					StartLine: startLine,
					EndLine:   endLine,
					StartIdx:  i,
					EndIdx:    j - 1,
				})
			}
		}
	}

	// Filter to signatures that have multiple occurrences
	// Then remove subsumed signatures
	cloneGroups := []CloneGroup{}
	for sig, occurrences := range signatureMap {
		if len(occurrences) > 1 {
			cloneGroups = append(cloneGroups, CloneGroup{
				Signature:  sig,
				Occurrences: occurrences,
			})
		}
	}

	// Remove duplicate signatures (subsumed clones)
	// Keep only the maximal ones
	filtered := removeSubsumed(cloneGroups)

	return filtered
}

func removeSubsumed(groups []CloneGroup) []CloneGroup {
	// A clone group is subsumed if its signature is a substring of another group's signature
	// But we need to be careful about what "subsumed" means here

	// Sort by signature length descending
	sort.Slice(groups, func(i, j int) bool {
		return len(strings.Split(groups[i].Signature, "|")) > len(strings.Split(groups[j].Signature, "|"))
	})

	// Keep only non-subsumed groups
	var result []CloneGroup
	for i, g1 := range groups {
		subsumed := false
		for j := 0; j < i; j++ {
			g2 := groups[j]
			// Check if g1 is subsumed by g2
			if isSubsumed(g1, g2) {
				subsumed = true
				break
			}
		}
		if !subsumed {
			result = append(result, g1)
		}
	}

	return result
}

func isSubsumed(g1, g2 CloneGroup) bool {
	// Check if g1's occurrences are all contained within g2's occurrences
	sig1 := strings.Split(g1.Signature, "|")
	sig2 := strings.Split(g2.Signature, "|")

	if len(sig1) >= len(sig2) {
		return false
	}

	// For each occurrence of g1
	for _, occ1 := range g1.Occurrences {
		found := false
		for _, occ2 := range g2.Occurrences {
			if occ1.File == occ2.File &&
				occ1.StartIdx >= occ2.StartIdx &&
				occ1.EndIdx <= occ2.EndIdx {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}

	return true
}

func buildSignature(tokens []TokenInfo) string {
	var parts []string
	for _, t := range tokens {
		parts = append(parts, tokenToString(t))
	}
	return strings.Join(parts, "|")
}

func outputNormal(cloneGroups []CloneGroup) {
	if len(cloneGroups) == 0 {
		fmt.Println("\nFound total 0 clone groups.")
		return
	}

	for _, group := range cloneGroups {
		fmt.Printf("found %d clones:\n", len(group.Occurrences))
		for _, occ := range group.Occurrences {
			fmt.Printf("  %s:%d,%d\n", occ.File, occ.StartLine, occ.EndLine)
		}
	}
	fmt.Printf("\nFound total %d clone groups.\n", len(cloneGroups))
}

func outputHTML(cloneGroups []CloneGroup, fileMap map[string][]TokenInfo) {
	fmt.Println(`<!DOCTYPE html>
<meta charset="utf-8"/>
<title>Duplicates</title>
<style>
	pre {
		background-color: #FFD;
		border: 1px solid #E2E2E2;
		padding: 1ex;
	}
</style>`)

	for cloneIdx, group := range cloneGroups {
		fmt.Printf("<h1>#%d found %d clones</h1>\n", cloneIdx+1, len(group.Occurrences))
		for _, occ := range group.Occurrences {
			fmt.Printf("<h2>%s:%d</h2>\n", occ.File, occ.StartLine)
			fmt.Printf("<pre>")
			// Extract source code for display
			if tokens, ok := fileMap[occ.File]; ok {
				for i := occ.StartIdx; i <= occ.EndIdx && i < len(tokens); i++ {
					if i > occ.StartIdx && tokens[i].Line > tokens[i-1].Line {
						fmt.Printf("\n")
					}
					if tokens[i].Value != "" && tokens[i].Type != token.SEMICOLON {
						fmt.Printf("%s ", tokens[i].Value)
					}
				}
			}
			fmt.Printf("</pre>\n")
		}
	}
}

func outputPlumbing(cloneGroups []CloneGroup) {
	for _, group := range cloneGroups {
		for i, occ := range group.Occurrences {
			if i == 0 && len(group.Occurrences) > 1 {
				fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n",
					occ.File, occ.StartLine, occ.EndLine,
					group.Occurrences[1].File, group.Occurrences[1].StartLine, group.Occurrences[1].EndLine)
			} else if i > 0 {
				fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n",
					occ.File, occ.StartLine, occ.EndLine,
					group.Occurrences[0].File, group.Occurrences[0].StartLine, group.Occurrences[0].EndLine)
			}
		}
	}
}
