func findClones(fileMap map[string][]TokenInfo, threshold int) []CloneGroup {
	// Build a map from signature to occurrences
	signatureMap := make(map[string][]CloneOccurrence)

	// For each file, find all token sequences >= threshold
	for filepath, tokens := range fileMap {
		// Find all maximal duplicate sequences for this file
		for i := 0; i < len(tokens); i++ {
			// Try sequences of increasing length starting at position i
			maxLen := 0
			var maxSig string

			for j := i + threshold; j <= len(tokens); j++ {
				sig := buildSignature(tokens[i:j])

				// Check if this signature appears elsewhere
				foundElsewhere := false
				for k := 0; k < len(tokens); k++ {
					if k == i {
						continue
					}
					if k+threshold <= len(tokens) && k+j-i <= len(tokens) {
						if buildSignature(tokens[k:k+j-i]) == sig {
							foundElsewhere = true
							break
						}
					}
				}

				if foundElsewhere {
					maxLen = j - i
					maxSig = sig
				} else {
					break
				}
			}

			if maxLen >= threshold {
				startLine := tokens[i].Line
				endLine := tokens[i+maxLen-1].Line

				signatureMap[maxSig] = append(signatureMap[maxSig], CloneOccurrence{
					File:      filepath,
					StartLine: startLine,
					EndLine:   endLine,
					StartIdx:  i,
					EndIdx:    i + maxLen - 1,
				})
			}
		}
	}

	// Actually this approach is still wrong. Let me think differently.
	// The real approach: find all signatures that appear multiple times in DIFFERENT files
	// OR multiple times in the SAME file

	signatureMap = make(map[string][]CloneOccurrence)

	// Build map of all contiguous sequences >= threshold
	for filepath, tokens := range fileMap {
		for i := 0; i <= len(tokens)-threshold; i++ {
			for j := i + threshold; j <= len(tokens); j++ {
				sig := buildSignature(tokens[i:j])
				startLine := tokens[i].Line
				endLine := tokens[j-1].Line

				signatureMap[sig] = append(signatureMap[sig], CloneOccurrence{
					File:      filepath,
					StartLine: startLine,
					EndLine:   endLine,
					StartIdx:  i,
					EndIdx:    j - 1,
				})
			}
		}
	}

	// Filter to signatures that have multiple occurrences
	// Then remove subsumed signatures
	cloneGroups := []CloneGroup{}
	for sig, occurrences := range signatureMap {
		if len(occurrences) > 1 {
			cloneGroups = append(cloneGroups, CloneGroup{
				Signature:  sig,
				Occurrences: occurrences,
			})
		}
	}

	// Remove duplicate signatures (subsumed clones)
	// Keep only the maximal ones
	filtered := removeSubsumed(cloneGroups)

	return filtered
}

func removeSubsumed(groups []CloneGroup) []CloneGroup {
	// A clone group is subsumed if its signature is a substring of another group's signature
	// But we need to be careful about what "subsumed" means here

	// Sort by signature length descending
	sort.Slice(groups, func(i, j int) bool {
		return len(strings.Split(groups[i].Signature, "|")) > len(strings.Split(groups[j].Signature, "|"))
	})

	// Keep only non-subsumed groups
	var result []CloneGroup
	for i, g1 := range groups {
		subsumed := false
		for j := 0; j < i; j++ {
			g2 := groups[j]
			// Check if g1 is subsumed by g2
			if isSubsumed(g1, g2) {
				subsumed = true
				break
			}
		}
		if !subsumed {
			result = append(result, g1)
		}
	}

	return result
}

func isSubsumed(g1, g2 CloneGroup) bool {
	// Check if g1's occurrences are all contained within g2's occurrences
	sig1 := strings.Split(g1.Signature, "|")
	sig2 := strings.Split(g2.Signature, "|")

	if len(sig1) >= len(sig2) {
		return false
	}

	// For each occurrence of g1
	for _, occ1 := range g1.Occurrences {
		found := false
		for _, occ2 := range g2.Occurrences {
			if occ1.File == occ2.File &&
				occ1.StartIdx >= occ2.StartIdx &&
				occ1.EndIdx <= occ2.EndIdx {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}

	return true
}

func buildSignature(tokens []TokenInfo) string {
	var parts []string
	for _, t := range tokens {
		parts = append(parts, tokenToString(t))
	}
	return strings.Join(parts, "|")
}

func outputNormal(cloneGroups []CloneGroup) {
	if len(cloneGroups) == 0 {
		fmt.Println("\nFound total 0 clone groups.")
		return
	}

	for _, group := range cloneGroups {
		fmt.Printf("found %d clones:\n", len(group.Occurrences))
		for _, occ := range group.Occurrences {
			fmt.Printf("  %s:%d,%d\n", occ.File, occ.StartLine, occ.EndLine)
		}
	}
	fmt.Printf("\nFound total %d clone groups.\n", len(cloneGroups))
}

func outputHTML(cloneGroups []CloneGroup, fileMap map[string][]TokenInfo) {
	fmt.Println(`<!DOCTYPE html>
<meta charset="utf-8"/>
<title>Duplicates</title>
<style>
	pre {
		background-color: #FFD;
		border: 1px solid #E2E2E2;
		padding: 1ex;
	}
</style>`)

	for cloneIdx, group := range cloneGroups {
		fmt.Printf("<h1>#%d found %d clones</h1>\n", cloneIdx+1, len(group.Occurrences))
		for _, occ := range group.Occurrences {
			fmt.Printf("<h2>%s:%d</h2>\n", occ.File, occ.StartLine)
			fmt.Printf("<pre>")
			// Extract source code for display
			if tokens, ok := fileMap[occ.File]; ok {
				for i := occ.StartIdx; i <= occ.EndIdx && i < len(tokens); i++ {
					if i > occ.StartIdx && tokens[i].Line > tokens[i-1].Line {
						fmt.Printf("\n")
					}
					if tokens[i].Value != "" && tokens[i].Type != token.SEMICOLON {
						fmt.Printf("%s ", tokens[i].Value)
					}
				}
			}
			fmt.Printf("</pre>\n")
		}
	}
}

func outputPlumbing(cloneGroups []CloneGroup) {
	for _, group := range cloneGroups {
		for i, occ := range group.Occurrences {
			if i == 0 && len(group.Occurrences) > 1 {
				fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n",
					occ.File, occ.StartLine, occ.EndLine,
					group.Occurrences[1].File, group.Occurrences[1].StartLine, group.Occurrences[1].EndLine)
			} else if i > 0 {
				fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n",
					occ.File, occ.StartLine, occ.EndLine,
					group.Occurrences[0].File, group.Occurrences[0].StartLine, group.Occurrences[0].EndLine)
			}
		}
	}
}
