		return
	}

	for _, group := range cloneGroups {
		fmt.Printf("found %d clones:\n", len(group.Occurrences))
		for _, occ := range group.Occurrences {
			fmt.Printf("  %s:%d,%d\n", occ.File, occ.StartLine, occ.EndLine)
		}
	}
