}

func outputHTML(cloneGroups []CloneGroup, fileMap map[string][]TokenInfo) {
	fmt.Println(`<!DOCTYPE html>
<meta charset="utf-8"/>
<title>Duplicates</title>
<style>
	pre {
		background-color: #FFD;
		border: 1px solid #E2E2E2;
		padding: 1ex;
	}
</style>`)

	for cloneIdx, group := range cloneGroups {
		fmt.Printf("<h1>#%d found %d clones</h1>\n", cloneIdx+1, len(group.Occurrences))
		for _, occ := range group.Occurrences {
