					}
					if tokens[i].Value != "" && tokens[i].Type != token.SEMICOLON {
						fmt.Printf("%s ", tokens[i].Value)
					}
				}
			}
			fmt.Printf("</pre>\n")
		}
	}
}

func outputPlumbing(cloneGroups []CloneGroup) {
	for _, group := range cloneGroups {
		for i, occ := range group.Occurrences {
			if i == 0 && len(group.Occurrences) > 1 {
				fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n",
					occ.File, occ.StartLine, occ.EndLine,
					group.Occurrences[1].File, group.Occurrences[1].StartLine, group.Occurrences[1].EndLine)
			} else if i > 0 {
				fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n",
					occ.File, occ.StartLine, occ.EndLine,
					group.Occurrences[0].File, group.Occurrences[0].StartLine, group.Occurrences[0].EndLine)
