var (
	flagThreshold = flag.Int("t", 15, "minimum token sequence size as a clone")
	flagHTML      = flag.Bool("html", false, "output the results as HTML, including duplicate code fragments")
	flagPlumbing  = flag.Bool("plumbing", false, "plumbing (easy-to-parse) output for consumption by scripts or tools")
	flagFiles     = flag.Bool("files", false, "read file names from stdin one at each line")
	flagVendor    = flag.Bool("vendor", false, "check files in vendor directory")
	flagVerbose   = flag.Bool("v", false, "explain what is being done")
)

func init() {
	flag.IntVar(flagThreshold, "threshold", 15, "minimum token sequence size as a clone")
	flag.BoolVar(flagVerbose, "verbose", false, "explain what is being done")
}

type TokenInfo struct {
	Type  token.Token
	Value string
	Line  int
	File  string
}

type CloneGroup struct {
	Signature  string
	Length     int
	Occurrences []CloneOccurrence
}

type CloneOccurrence struct {
	File      string
	StartLine int
	EndLine   int
	StartIdx  int
	EndIdx    int
}

func main() {
	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(), `Usage: dupl [flags] [paths]

Paths:
  If the given path is a file, dupl will use it regardless of
  the file extension. If it is a directory, it will recursively
  search for *.go files in that directory.

  If no path is given, dupl will recursively search for *.go
  files in the current directory.

Flags:
`)
		flag.PrintDefaults()
		fmt.Fprintf(flag.CommandLine.Output(), `
Examples:
  dupl -t 100
    	Search clones in the current directory of size at least
    	100 tokens.
  dupl $(find app/ -name '*_test.go')
    	Search for clones in tests in the app directory.
  find app/ -name '*_test.go' |dupl -files
    	The same as above.
`)
	}

	flag.Parse()

	if *flagHTML && *flagPlumbing {
		log.Fatal("you can have either plumbing or HTML output")
	}

	var goFiles []string

	if *flagFiles {
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			goFiles = append(goFiles, scanner.Text())
		}
		if err := scanner.Err(); err != nil {
			log.Fatal(err)
		}
	} else {
		paths := flag.Args()
		if len(paths) == 0 {
			paths = []string{"."}
		}
		for _, p := range paths {
			files, err := walkGo(p, *flagVendor)
			if err != nil {
				log.Fatal(err)
			}
			goFiles = append(goFiles, files...)
		}
	}

	if *flagVerbose {
		log.Println("Building suffix tree")
	}

	// Parse tokens from all files
	fileMap := make(map[string][]TokenInfo)
	for _, f := range goFiles {
		tokens, err := tokenizeFile(f)
		if err != nil {
			if *flagVerbose {
				log.Printf("Error tokenizing %s: %v", f, err)
			}
			continue
		}
		if len(tokens) > 0 {
			fileMap[f] = tokens
		}
	}

	if *flagVerbose {
		log.Println("Searching for clones")
	}

	// Find clones - generate signatures for all subsequences
	cloneMap := make(map[string][]CloneOccurrence)
	for filePath, tokens := range fileMap {
		for i := 0; i < len(tokens); i++ {
			for j := i + *flagThreshold; j <= len(tokens); j++ {
				sig := buildSignature(tokens[i:j])
				startLine := tokens[i].Line
				endLine := tokens[j-1].Line
				cloneMap[sig] = append(cloneMap[sig], CloneOccurrence{
					File:      filePath,
					StartLine: startLine,
					EndLine:   endLine,
					StartIdx:  i,
					EndIdx:    j - 1,
				})
			}
		}
	}

	// Filter duplicates and build groups
	var cloneGroups []CloneGroup
	for sig, occurrences := range cloneMap {
		if len(occurrences) > 1 {
			sigLength := len(strings.Split(sig, "|"))
			cloneGroups = append(cloneGroups, CloneGroup{
				Signature:  sig,
				Length:     sigLength,
				Occurrences: occurrences,
			})
		}
	}

	// Sort by length (descending), then by position
	sort.Slice(cloneGroups, func(i, j int) bool {
		if cloneGroups[i].Length != cloneGroups[j].Length {
			return cloneGroups[i].Length > cloneGroups[j].Length
		}
		if cloneGroups[i].Occurrences[0].File != cloneGroups[j].Occurrences[0].File {
			return cloneGroups[i].Occurrences[0].File < cloneGroups[j].Occurrences[0].File
		}
		return cloneGroups[i].Occurrences[0].StartLine < cloneGroups[j].Occurrences[0].StartLine
	})

	// Filter out occurrences that are subsumed by larger clones
	cloneGroups = filterSubsumedOccurrences(cloneGroups)

	// Output results
	if *flagHTML {
		outputHTML(cloneGroups, fileMap)
	} else if *flagPlumbing {
		outputPlumbing(cloneGroups)
	} else {
		outputNormal(cloneGroups)
	}
}

func filterSubsumedOccurrences(groups []CloneGroup) []CloneGroup {
	// For each group, check if its occurrences are subsumed by larger groups
	// If so, remove this group entirely

	var result []CloneGroup
	for i, group := range groups {
		subsumed := false

		// Check if all occurrences of this group are contained in larger groups
		for j := 0; j < i; j++ {
			largerGroup := groups[j]

			// Check if all occurrences of group are contained in largerGroup
			allContained := true
			for _, occ := range group.Occurrences {
				found := false
				for _, largerOcc := range largerGroup.Occurrences {
					if occ.File == largerOcc.File &&
						occ.StartIdx >= largerOcc.StartIdx &&
						occ.EndIdx <= largerOcc.EndIdx {
