	"fmt"
	"go/scanner"
	"go/token"
	"io/ioutil"
	"strings"
)

type TokenInfo struct {
	Type  token.Token
	Value string
	Line  int
}

func tokenizeFile(filepath string) ([]TokenInfo, error) {
	source, err := ioutil.ReadFile(filepath)
	if err != nil {
		return nil, err
	}

	fset := token.NewFileSet()
	var s scanner.Scanner
	s.Init(fset.AddFile(filepath, fset.Base(), len(source)), source, nil, 0)

	var tokens []TokenInfo

	for {
		pos, tok, lit := s.Scan()
		if tok == token.EOF {
			break
		}
		p := fset.Position(pos)
		tokens = append(tokens, TokenInfo{
			Type:  tok,
			Value: lit,
			Line:  p.Line,
		})
	}

	return tokens, nil
}

func tokenToString(t TokenInfo) string {
	if t.Type == token.IDENT {
		return "IDENT"
	}
	return fmt.Sprintf("%s:%s", t.Type.String(), t.Value)
}

func buildSignature(tokens []TokenInfo) string {
	var parts []string
	for _, t := range tokens {
		parts = append(parts, tokenToString(t))
	}
	return strings.Join(parts, "|")
}

func main() {
	flag.Parse()
	filepath := flag.Arg(0)
	threshold := 15

	tokens, _ := tokenizeFile(filepath)

	// Find matching sequences
	sigMap := make(map[string][]int)
	for i := 0; i <= len(tokens)-threshold; i++ {
		for j := i + threshold; j <= len(tokens); j++ {
			sig := buildSignature(tokens[i:j])
			sigMap[sig] = append(sigMap[sig], i)
		}
	}

	// Find duplicates
	for sig, positions := range sigMap {
		if len(positions) > 1 {
			fmt.Printf("Signature (len %d): %s\n", len(strings.Split(sig, "|")), sig[:100])
			for _, pos := range positions {
				endPos := pos + len(strings.Split(sig, "|")) - 1
				fmt.Printf("  Tokens %d-%d: lines %d-%d\n", pos, endPos, tokens[pos].Line, tokens[endPos].Line)
			}
		}
	}
}
EOF

