package main

import (
	"bufio"
	"flag"
	"fmt"
	"go/scanner"
	"go/token"
	"io/ioutil"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

var (
	flagThreshold = flag.Int("t", 15, "minimum token sequence size as a clone")
	flagHTML      = flag.Bool("html", false, "output the results as HTML, including duplicate code fragments")
	flagPlumbing  = flag.Bool("plumbing", false, "plumbing (easy-to-parse) output for consumption by scripts or tools")
	flagFiles     = flag.Bool("files", false, "read file names from stdin one at each line")
	flagVendor    = flag.Bool("vendor", false, "check files in vendor directory")
	flagVerbose   = flag.Bool("v", false, "explain what is being done")
)

func init() {
	flag.IntVar(flagThreshold, "threshold", 15, "minimum token sequence size as a clone")
	flag.BoolVar(flagVerbose, "verbose", false, "explain what is being done")
}

type TokenInfo struct {
	Type  token.Token
	Value string
	Line  int
	File  string
}

type CloneGroup struct {
	Signature  string
	Length     int
	Occurrences []CloneOccurrence
}

type CloneOccurrence struct {
	File      string
	StartLine int
	EndLine   int
	StartIdx  int
	EndIdx    int
}

func main() {
	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(), `Usage: dupl [flags] [paths]

Paths:
  If the given path is a file, dupl will use it regardless of
  the file extension. If it is a directory, it will recursively
  search for *.go files in that directory.

  If no path is given, dupl will recursively search for *.go
  files in the current directory.

Flags:
`)
		flag.PrintDefaults()
		fmt.Fprintf(flag.CommandLine.Output(), `
Examples:
  dupl -t 100
    	Search clones in the current directory of size at least
    	100 tokens.
  dupl $(find app/ -name '*_test.go')
    	Search for clones in tests in the app directory.
  find app/ -name '*_test.go' |dupl -files
    	The same as above.
`)
	}

	flag.Parse()

	if *flagHTML && *flagPlumbing {
		log.Fatal("you can have either plumbing or HTML output")
	}

	var goFiles []string

	if *flagFiles {
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			goFiles = append(goFiles, scanner.Text())
		}
		if err := scanner.Err(); err != nil {
			log.Fatal(err)
		}
	} else {
		paths := flag.Args()
		if len(paths) == 0 {
			paths = []string{"."}
		}
		for _, p := range paths {
			files, err := walkGo(p, *flagVendor)
			if err != nil {
				log.Fatal(err)
			}
			goFiles = append(goFiles, files...)
		}
	}

	if *flagVerbose {
		log.Println("Building suffix tree")
	}

	fileMap := make(map[string][]TokenInfo)
	for _, f := range goFiles {
		tokens, err := tokenizeFile(f)
		if err != nil {
			if *flagVerbose {
				log.Printf("Error tokenizing %s: %v", f, err)
			}
			continue
		}
		if len(tokens) > 0 {
			fileMap[f] = tokens
		}
	}

	if *flagVerbose {
		log.Println("Searching for clones")
	}

	cloneGroups := findClones(fileMap, *flagThreshold)

	sort.Slice(cloneGroups, func(i, j int) bool {
		if len(cloneGroups[i].Occurrences) != len(cloneGroups[j].Occurrences) {
			return len(cloneGroups[i].Occurrences) > len(cloneGroups[j].Occurrences)
		}
		if cloneGroups[i].Occurrences[0].File != cloneGroups[j].Occurrences[0].File {
			return cloneGroups[i].Occurrences[0].File < cloneGroups[j].Occurrences[0].File
		}
		return cloneGroups[i].Occurrences[0].StartLine < cloneGroups[j].Occurrences[0].StartLine
	})

	if *flagHTML {
		outputHTML(cloneGroups, fileMap)
	} else if *flagPlumbing {
		outputPlumbing(cloneGroups)
	} else {
		outputNormal(cloneGroups)
	}
}

func walkGo(root string, includeVendor bool) ([]string, error) {
	var result []string
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			if !includeVendor && info.Name() == "vendor" {
				return filepath.SkipDir
			}
			return nil
		}
		if strings.HasSuffix(path, ".go") {
			result = append(result, path)
		}
		return nil
	})
	return result, err
}

func tokenizeFile(filepath string) ([]TokenInfo, error) {
	source, err := ioutil.ReadFile(filepath)
	if err != nil {
		return nil, err
	}

	fset := token.NewFileSet()
	var s scanner.Scanner
	s.Init(fset.AddFile(filepath, fset.Base(), len(source)), source, nil, 0)

	var tokens []TokenInfo

	for {
		pos, tok, lit := s.Scan()
		if tok == token.EOF {
			break
		}
		p := fset.Position(pos)
		tokens = append(tokens, TokenInfo{
			Type:  tok,
			Value: lit,
			Line:  p.Line,
			File:  filepath,
		})
	}

	return tokens, nil
}

func tokenToString(t TokenInfo) string {
	if t.Type == token.IDENT {
		return "IDENT"
	}
	return fmt.Sprintf("%s:%s", t.Type.String(), t.Value)
}

func buildSignature(tokens []TokenInfo) string {
	var parts []string
	for _, t := range tokens {
		parts = append(parts, tokenToString(t))
	}
	return strings.Join(parts, "|")
}

func findClones(fileMap map[string][]TokenInfo, threshold int) []CloneGroup {
	// Find all candidate sequences >= threshold
	type CandidateSeq struct {
		sig    string
		file   string
		startLine int
		endLine   int
		startIdx  int
		endIdx    int
		length    int
	}

	var candidates []CandidateSeq

	for file, tokens := range fileMap {
		for i := 0; i <= len(tokens)-threshold; i++ {
			// Find the longest match starting at position i
