				})
			}
		}
	}

	// Group by signature
	sigMap := make(map[string][]CandidateSeq)
	for _, cand := range candidates {
		sigMap[cand.sig] = append(sigMap[cand.sig], cand)
	}

	// Build clone groups from duplicates
	var groups []CloneGroup
	for sig, seqs := range sigMap {
		if len(seqs) > 1 {
			var occs []CloneOccurrence
			for _, seq := range seqs {
				occs = append(occs, CloneOccurrence{
					File:      seq.file,
					StartLine: seq.startLine,
					EndLine:   seq.endLine,
					StartIdx:  seq.startIdx,
					EndIdx:    seq.endIdx,
