func tokenToString(t TokenInfo) string {
	if t.Type == token.IDENT {
		return "IDENT"
	}
	return fmt.Sprintf("%s:%s", t.Type.String(), t.Value)
}

func buildSignature(tokens []TokenInfo) string {
	var parts []string
	for _, t := range tokens {
		parts = append(parts, tokenToString(t))
	}
	return strings.Join(parts, "|")
}

func findClones(fileMap map[string][]TokenInfo, threshold int) []CloneGroup {
	// Find all candidate sequences >= threshold
	type CandidateSeq struct {
		sig    string
		file   string
		startLine int
		endLine   int
		startIdx  int
		endIdx    int
		length    int
	}

	var candidates []CandidateSeq

	for file, tokens := range fileMap {
		for i := 0; i <= len(tokens)-threshold; i++ {
			// Find the longest match starting at position i
			maxJ := i + threshold
			for j := i + threshold; j <= len(tokens); j++ {
				sig := buildSignature(tokens[i:j])
				// Check if this exact signature appears elsewhere
				foundElsewhere := false
				for file2, tokens2 := range fileMap {
					if file == file2 {
						// Check other positions in same file
						for k := i + 1; k <= len(tokens2)-( j-i); k++ {
							if buildSignature(tokens2[k:k+(j-i)]) == sig {
								foundElsewhere = true
								break
							}
						}
					} else {
						// Check all positions in other files
						if j-i <= len(tokens2) {
							for k := 0; k <= len(tokens2)-(j-i); k++ {
								if buildSignature(tokens2[k:k+(j-i)]) == sig {
									foundElsewhere = true
									break
								}
							}
						}
					}
					if foundElsewhere {
						break
					}
				}

				if foundElsewhere {
					maxJ = j
				} else {
					break
				}
			}

			if maxJ > i + threshold {
				sig := buildSignature(tokens[i:maxJ])
				candidates = append(candidates, CandidateSeq{
					sig:       sig,
					file:      file,
					startLine: tokens[i].Line,
					endLine:   tokens[maxJ-1].Line,
					startIdx:  i,
					endIdx:    maxJ - 1,
					length:    maxJ - i,
				})
			}
		}
	}

