	return fmt.Sprintf("%s:%s", t.Type.String(), t.Value)
}

func buildSignature(tokens []TokenInfo) string {
	var parts []string
	for _, t := range tokens {
		parts = append(parts, tokenToString(t))
	}
	return strings.Join(parts, "|")
}

func findClones(fileMap map[string][]TokenInfo, threshold int) [][]CloneOccurrence {
	// Build map of all signatures >= threshold to their occurrences
	sigMap := make(map[string][]CloneOccurrence)

	for file, tokens := range fileMap {
		for i := 0; i <= len(tokens)-threshold; i++ {
			for j := i + threshold; j <= len(tokens); j++ {
				sig := buildSignature(tokens[i:j])
				sigMap[sig] = append(sigMap[sig], CloneOccurrence{
					File: file,
					StartLine: tokens[i].Line,
					EndLine: tokens[j-1].Line,
					StartIdx: i,
					EndIdx: j - 1,
				})
			}
		}
	}

	// Filter and remove subsumed signatures
	var groups [][]CloneOccurrence
	for sig, occs := range sigMap {
		if len(occs) > 1 {
			// Sort occurrences
			sort.Slice(occs, func(i, j int) bool {
				if occs[i].File != occs[j].File {
					return occs[i].File < occs[j].File
				}
				return occs[i].StartLine < occs[j].StartLine
			})
			groups = append(groups, occs)
		}
	}

	// Remove subsumed groups - keep only maximal non-overlapping ones
	groups = removeSubsumedGroups(groups)

	return groups
}

func removeSubsumedGroups(groups [][]CloneOccurrence) [][]CloneOccurrence {
	// Sort by group size descending
	sort.Slice(groups, func(i, j int) bool {
		sizei := groups[i][0].EndIdx - groups[i][0].StartIdx
		sizej := groups[j][0].EndIdx - groups[j][0].StartIdx
		return sizei > sizej
	})

	var result [][]CloneOccurrence
	for i, group1 := range groups {
		subsumed := false
		for j := 0; j < i; j++ {
			group2 := groups[j]
			// Check if all occurrences of group1 are contained in group2 occurrences
			allContained := true
			for _, occ1 := range group1 {
				found := false
				for _, occ2 := range group2 {
					if occ1.File == occ2.File &&
						occ1.StartIdx >= occ2.StartIdx &&
						occ1.EndIdx <= occ2.EndIdx {
						found = true
						break
					}
				}
				if !found {
					allContained = false
					break
				}
			}
			if allContained {
				subsumed = true
				break
			}
		}
		if !subsumed {
			result = append(result, group1)
		}
	}

	return result
}

