		fmt.Printf("found %d clones:\n", len(group))
		for _, occ := range group {
			fmt.Printf("  %s:%d,%d\n", occ.File, occ.StartLine, occ.EndLine)
		}
	}
	fmt.Printf("\nFound total %d clone groups.\n", len(cloneGroups))
}

func outputHTML(cloneGroups [][]CloneOccurrence, fileMap map[string][]TokenInfo) {
	fmt.Println(`<!DOCTYPE html>
<meta charset="utf-8"/>
<title>Duplicates</title>
<style>
	pre {
		background-color: #FFD;
		border: 1px solid #E2E2E2;
		padding: 1ex;
	}
</style>`)

	for cloneIdx, group := range cloneGroups {
		fmt.Printf("<h1>#%d found %d clones</h1>\n", cloneIdx+1, len(group))
		for _, occ := range group {
			fmt.Printf("<h2>%s:%d</h2>\n", occ.File, occ.StartLine)
			fmt.Printf("<pre>")
			if tokens, ok := fileMap[occ.File]; ok {
				for i := occ.StartIdx; i <= occ.EndIdx && i < len(tokens); i++ {
					if i > occ.StartIdx && tokens[i].Line > tokens[i-1].Line {
						fmt.Printf("\n")
					}
					if tokens[i].Value != "" && tokens[i].Type != token.SEMICOLON {
						fmt.Printf("%s ", tokens[i].Value)
					}
				}
			}
			fmt.Printf("</pre>\n")
		}
	}
}

func outputPlumbing(cloneGroups [][]CloneOccurrence) {
	for _, group := range cloneGroups {
		for i, occ := range group {
			if i == 0 && len(group) > 1 {
				fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n",
					occ.File, occ.StartLine, occ.EndLine,
					group[1].File, group[1].StartLine, group[1].EndLine)
			} else if i > 0 {
				fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n",
					occ.File, occ.StartLine, occ.EndLine,
					group[0].File, group[0].StartLine, group[0].EndLine)
			}
		}
	}
}
